{
  "messages": [
    {
      "time": "10:45",
      "author": "Timo Laine",
      "role": "Field Engineer",
      "text": "Just driving back from OULU-07 after a quick routine check near TRN-045. Are you up for some lunch today Anu?"
    },
    {
      "time": "10:48",
      "author": "Anu Virtanen",
      "role": "Network Expert",
      "text": "Hey Timo! Yes, definitely. By the way, just heard that our Thursday planning meeting got moved to Friday at 13:00."
    },
    {
      "time": "10:51",
      "author": "Timo Laine",
      "role": "Field Engineer",
      "text": "Oh thanks for the heads up, Friday afternoon is always a classic time for planning. How about we head to the canteen at 11:30? It's soup day today!"
    },
    {
      "time": "10:53",
      "author": "Anu Virtanen",
      "role": "Network Expert",
      "text": "Perfect, 11:30 works great. I really need a break, been fighting with the office coffee machine again."
    },
    {
      "time": "10:55",
      "author": "Timo Laine",
      "role": "Field Engineer",
      "text": "Haha, that coffee machine is easily the least reliable device on our entire network. It needs a complete hardware swap."
    },
    {
      "time": "10:58",
      "author": "Anu Virtanen",
      "role": "Network Expert",
      "text": "Absolutely, it has a 90% packet loss on espresso delivery! See you at 11:30 at the canteen :)"
    }
  ]
}
